// node scripts/studio/save-last.mjs <out.jpg> — saves the newest generated
// image in the open chat (e.g. one you generated by hand in the page).
import { writeFile } from 'node:fs/promises'
import { fetchImage, listImages, withStudio } from './connect.mjs'

const out = process.argv[2]

await withStudio(async (page) => {
  const src = (await listImages(page)).at(-1)
  if (!src) throw new Error('No generated image in this chat')
  const { type, data } = await fetchImage(page, src)
  await writeFile(out, Buffer.from(data, 'base64'))
  console.log('saved', out, type)
})
